# A level cut from the gis base map (map::compose). Edit with:
# cargo run -- --campaign-editor gis --level 4

[properties]
name: The Long Road
stories: campaigns/gis/gis_04/gis_04_story.ron
loot: 1-3 per 40
escape_limit: 6
coins: 300
townsfolk: 18
base: campaigns/gis/world/world.map
region: 130, 100, 100, 100

[markers]
# marker: player | spawn | goal | at: <x, y in the base map's tiles>
marker: goal | at: 179, 150
marker: player | at: 181, 150
marker: spawn | at: 156, 100
marker: spawn | at: 142, 199
marker: spawn | at: 130, 193
marker: spawn | at: 130, 186

[placements]
# at: x, y | def: <def under assets/, e.g. defs/Barrel.ron> | rotation: <degrees, steps of 45>

[waves]
# enemy: <enemy def under assets/, omit for the built-in alien> | count: <n> | rate: <per minute>
enemy: defs/Alpaking.ron | count: 10 | rate: 12
enemy: defs/Stone Golem.ron | count: 4 | rate: 4
enemy: defs/Bunny.ron | count: 20 | rate: 24
enemy: defs/Blue Demon.ron | count: 8 | rate: 8
count: 30 | rate: 24
